    correct: 2,
    explanation: "## Inches to Centimetres\n\nA screen listed as fifteen inches needs to be reported in centimetres for an international catalogue. The conversion is a single multiplication by unity.\n\n**The formula.**\n\\[ \\text{Length in cm} = \\text{Length in inches} \\times \\left( \\frac{2.54\\text{ cm}}{1\\text{ in.}} \\right) \\]\n\n**Substituting.**\n\\[ \\text{Length} = 15.0\\text{ in.} \\times \\frac{2.54\\text{ cm}}{1\\text{ in.}} \\]\n\n**Evaluating.**\n\\[ \\text{Length} = 38.1\\text{ cm} \\]\n\nThe inch units cancel, leaving centimetres as the surviving unit. The number is 15.0 multiplied by 2.54, which gives 38.1.\n\nIf the answer comes out to roughly 5.91 instead, the fraction was inverted, and the calculation was dividing by 2.54 rather than multiplying by it. If it comes out to 17.54, the fraction was interpreted as addition.\n\nThe conversion is not a separate step to memorise. It is a fraction equal to one, arranged so the units cancel correctly. When you write the fraction, always place the unit you want to eliminate in the denominator.",
