    explanation: "## Cubing the Conversion\n\nA millilitre of water is exactly one cubic centimetre. When the same volume needs to be reported in cubic metres, the conversion is not a single multiplication by one hundred. It is cubing the linear conversion.\n\n**The formula.**\nSince \\(1\\text{ cm} = 10^{-2}\\text{ m}\\), the volume conversion requires cubing both sides:\n\\[ 1\\text{ cm}^{3} = \\left(10^{-2}\\text{ m}\\right)^{3} \\]\n\n**Substituting.**\n\\[ 1\\text{ cm}^{3} = 10^{-6}\\text{ m}^{3} \\]\n\n**Evaluating.**\n\\[ 8.560\\text{ cm}^{3} = 8.560 \\times 10^{-6}\\text{ m}^{3} \\]\n\nThe trick with cubed or squared units is that the exponent on the conversion factor must match the power of the unit. Converting a length uses \\(10^{-2}\\), converting an area uses \\(10^{-4}\\), and converting a volume uses \\(10^{-6}\\).\n\nWhen you convert a raised unit, cube or square the conversion factor itself, not just the unit. A volume conversion that uses a length factor is off by a factor of ten thousand.",
