    explanation: "## The Size of an Acre\n\nAn acre is a land measure older than the metric system. Its size has to be translated into square metres for modern legal documents, and the translation runs through miles and feet.\n\nFirst find a square mile in square feet, then divide by 640, then convert to square metres.\n\\[ 1\\text{ mi}^{2} = (5280\\text{ ft})^{2} \\]\n\\[ 1\\text{ acre} = \\frac{1\\text{ mi}^{2}}{640} \\]\n\n\\[ 1\\text{ mi}^{2} = 27,878,400\\text{ ft}^{2} \\]\n\\[ 1\\text{ acre} = \\frac{27,878,400}{640}\\text{ ft}^{2} = 43,560\\text{ ft}^{2} \\]\n\n\\[ 1\\text{ acre} = \\frac{43,560}{10.76}\\text{ m}^{2} \\approx 4048\\text{ m}^{2} \\]\n\nEach step changes one unit at a time. The chain would be broken if the mile were converted to metres directly while the acre were kept in imperial units.\n\nWhen an area conversion travels through multiple units, keep the squared units squared throughout. Dividing a squared unit by a linear factor is the most common way an area conversion collapses.",
