    explanation: "## Distance Over Time in Letter Form\n\nStrip speed down to what it actually is: distance divided by time. Distance has the dimension \\(L\\), and time has the dimension \\(T\\). The division therefore gives a dimension of \\(L\\) over \\(T\\), which is written \\(LT^{-1}\\).\n\n\\[ [v] = \\frac{\\text{Distance}}{\\text{Time}} \\]\n\n\\[ [v] = \\frac{L}{T} \\]\n\n\\[ [v] = LT^{-1} \\]\n\nEach derived quantity's dimensional formula can be built by substituting its definition. Acceleration is speed over time, so its dimension is \\(\\frac{L}{T^{2}}\\) or \\(LT^{-2}\\).\n\nNotice how close \\(LT^{-1}\\) is to \\(LT^{-2}\\). The two differ only by one power of \\(T\\), but that one power is what separates speed from acceleration. In dimensional analysis, small exponent differences matter.\n\nWhen you write a dimensional formula, do not guess at it. Expand the definition of the quantity into fundamentals, simplify, and let the exponents tell you what the formula is.",
