    correct: 1,
    explanation: "## Matching Units Term by Term\n\nAn equation that adds terms must have all its terms carrying the same unit. Otherwise the addition is meaningless, like adding metres to seconds.\n\nIn \\(x = a + bt + ct^{2}\\), every term must have the unit of \\(x\\), which is metres.\n\n\\[ \\text{Unit}(ct^2) = \\text{Unit}(x) \\]\n\\[ \\text{Unit}(c) \\cdot \\text{Unit}(t^2) = \\text{Unit}(x) \\]\n\nThe term \\(ct^{2}\\) therefore has unit \\(\\text{m}\\), and \\(t^{2}\\) has unit \\(\\text{s}^{2}\\).\n\\[ \\text{Unit}(c) \\cdot \\text{s}^2 = \\text{m} \\]\n\n\\[ \\text{Unit}(c) = \\frac{\\text{m}}{\\text{s}^{2}} = \\text{m/s}^{2} \\]\n\nThe same logic gives \\(b\\) the unit \\(\\text{m/s}\\) and \\(a\\) the unit \\(\\text{m}\\). Each coefficient takes whatever unit makes its term match the variable's unit.\n\nWhen an equation is a sum of terms, split it term by term. The variable's unit divided by the modifier's unit gives the coefficient's unit.",
