    correct: 0,
    explanation: "## Checking a Familiar Equation\n\nEvery term in an equation must have the same dimension. For \\(v = v_{0} + at\\), there are three terms to check: \\(v\\), \\(v_{0}\\), and \\(at\\).\n\nVelocities \\(v\\) and \\(v_{0}\\) both have dimension \\(LT^{-1}\\). We must check the term \\(at\\).\n\n\\[ [a] = LT^{-2} \\]\n\\[ [t] = T \\]\n\\[ [at] = (LT^{-2})(T) \\]\n\n\\[ [at] = LT^{-1} \\]\n\nAll three terms carry the same dimension \\(LT^{-1}\\). The equation is dimensionally homogeneous, so it is dimensionally correct.\n\nDimensional correctness is necessary but not sufficient. The equation could still be physically wrong if it had a stray coefficient like 2 or a wrong sign. But dimensional analysis rules out a large class of errors. When you learn a new equation in an exam, checking that every term matches is a two-second guard against memorising the wrong form.",
