    correct: 1,
    explanation: "## Where the Tool Stops\n\nA ruler measures length precisely and measures temperature not at all. Not because the ruler is defective, but because temperature is outside what a ruler can measure. Dimensional analysis has boundaries too.\n\nOne of its core **limitations** is that it cannot determine **numerical constants with no dimensions**.\n\nConsider two equations:\n\\[ A = 2\\pi r^2 \\]\n\\[ A = 4\\pi r^2 \\]\n\nApply dimensional analysis to both:\n\\[ [A] = [r]^2 = L^2 \\]\nBoth equations yield the exact same dimensional result.\n\nConstants like \\(\\pi\\), 2, or \\(\\frac{1}{2}\\) do not carry dimensions, so they do not appear in the dimension equation at all. Only the derivation tells you which one is right.\n\nWhen you use dimensional analysis, know what it gives you and what it does not. The dimensionless constants are always outside its reach, and no amount of dimensional reasoning will recover them.",
