    correct: 1,
    explanation: "## A Number Without a Dimension\n\nConsider what \\(\\pi\\) actually is. It is a ratio: circumference divided by diameter. Both are lengths, so the ratio has no dimension. It is a pure number, roughly 3.14159.\n\n\\[ \\pi = \\frac{C}{d} \\]\n\\[ [\\pi] = \\frac{[L]}{[L]} = 1 \\]\n\nDimensional analysis works by matching dimensions. A pure number has no dimensions to match. When you look at \\(A = \\pi r^{2}\\), the dimension check gives \\(L^{2}\\) on both sides regardless of whether \\(\\pi\\) is 3.14, 6.28, or any other number.\n\nThe value of \\(\\pi\\) comes from geometry, not from dimensional analysis. It was determined by comparing the circumference of a circle to its diameter.\n\nWhen you meet a dimensionless constant in a formula, do not expect dimensional analysis to help. Its value comes from derivation and experiment.",
