    explanation: "## Leading Zeros Never Count\n\nIn \\(0.543\\), the zero sits before the first non-zero digit. It is a **leading zero**, and leading zeros are never significant. They are only placeholders showing where the decimal sits.\n\nIdentify the first non-zero digit from the left. All digits from that point to the end (excluding placeholders in whole numbers without decimals) are significant.\n\nFor \\(0.543\\), the first non-zero is 5. Count from 5: \\(5, 4, 3\\). Total = 3.\nFor \\(0.06\\), the first non-zero is 6. Count from 6: \\(6\\). Total = 1.\n\nThe digits that count are 5, 4, and 3, giving three significant figures. In \\(0.06\\), the zero before the decimal is a leading zero, and the zero after the decimal but before the 6 is also a leading zero. The only significant digit is 6, giving one significant figure.\n\nThe pattern is consistent: leading zeros are placeholders, trailing zeros after a decimal are significant. When counting significant figures in a small decimal, ignore all zeros at the front and count only from the first non-zero digit onwards.",
    status: "approved"
