    correct: 2,
    explanation: "## Limiting Precision in Practice\n\nThe raw arithmetic is \\(12.5 + 3.456 = 15.956\\). The question is not what the raw arithmetic gives, but what the measurement precision permits.\n\n\\[ \\text{Decimal places of result} = \\min(\\text{Decimal places of terms}) \\]\n\nThe first term, \\(12.5\\), has one decimal place. The second term, \\(3.456\\), has three decimal places. The minimum is 1.\n\nThe addition rule limits the result to one decimal place. So the answer is reported as \\(16.0\\text{ cm}\\), with one decimal place.\n\nNotice that the retained decimal here is the 9 that becomes a 0 after rounding. The full sum 15.956 rounds to 16.0 to one decimal place. Writing 15.956 would claim precision that the measurement did not support. Writing 16 would go too far in the other direction and lose the decimal precision the limiting term allows.\n\nWhen you add or subtract, do the arithmetic first, then apply the decimal-place limit as a rounding step.",
