    correct: 0,
    explanation: "## Error as a Fraction of Truth\n\nAn absolute error of \\(1\\text{ cm}\\) is small in a \\(1\\text{ km}\\) measurement and enormous in a \\(3\\text{ cm}\\) measurement. The **relative error** measures how large the error is compared to the size of the quantity, which is why it lets two measurements be compared on the same footing.\n\n\\[ \\text{Relative Error} = \\frac{\\text{Mean Absolute Error}}{\\text{True Value}} \\]\n\nIf the mean absolute error is \\(0.2\\text{ cm}\\) and the true value is \\(10.0\\text{ cm}\\), we substitute:\n\\[ \\text{Relative Error} = \\frac{0.2}{10.0} \\]\n\n\\[ \\text{Relative Error} = 0.02 \\]\n\nThe result is a fraction or a small decimal. A relative error of \\(0.02\\) means the measurement is off by 2% of the true value. To express it as a percentage, multiply by 100.\n\nBecause relative error is dimensionless, it travels well between different units. When comparing precision across measurements, use relative error rather than absolute error.",
    status: "approved"
