    correct: 1,
    explanation: "## Powers Amplify Errors\n\nA quantity raised to a power magnifies its error. If you square a value with a 3% error, the squared value has a 6% error, not 3% and not 9%.\n\nThe **power rule** combines this amplification across all factors.\n\nFor \\(x = \\frac{a^{l} \\cdot b^{m}}{c^{n}}\\), the maximum relative error is:\n\\[ \\frac{\\Delta x}{x} = l\\frac{\\Delta a}{a} + m\\frac{\\Delta b}{b} + n\\frac{\\Delta c}{c} \\]\n\nIf \\(a\\) has a 1% error, \\(b\\) has a 2% error, and \\(c\\) has a 3% error, for \\(x = \\frac{a^2 b}{c^3}\\):\n\\[ \\frac{\\Delta x}{x} = 2(1\\%) + 1(2\\%) + 3(3\\%) \\]\n\n\\[ \\frac{\\Delta x}{x} = 2\\% + 2\\% + 9\\% = 13\\% \\]\n\nEach factor contributes its relative error multiplied by the power it is raised to. A factor raised to the fourth power contributes four times its relative error to the total.\n\nThis is why some measurements need to be more precise than others in a formula. A factor raised to a high power dominates the final error budget.",
    status: "approved"
