    correct: 1,
    explanation: "## Density as a Conversion Factor\n\nA density of \\(8.93\\text{ g/cm}^{3}\\) can be read as a statement about the material: each cubic centimetre of copper contains \\(8.93\\text{ g}\\) of mass. It is not a formula to memorise; it is a direct translation.\n\n\\[ m = \\rho \\cdot V \\]\n\nIf \\(1\\text{ cm}^{3}\\) of copper holds \\(8.93\\text{ g}\\), then:\n\\[ m = 8.93\\text{ g/cm}^{3} \\times 1\\text{ cm}^{3} \\]\n\n\\[ m = 8.93\\text{ g} \\]\n\nThe arithmetic is trivial. The important move is recognising that density is a rate. It tells you grams per cubic centimetre, and multiplying by the number of cubic centimetres gives the total grams.\n\nWhen a problem gives you density and one other quantity, set up the multiplication that leaves you with the desired unit. Density times volume gives mass. Mass divided by density gives volume.",
