    explanation: "## The Mass of a Single Atom\n\nA mole of aluminium has 27 grams and Avogadro's number of atoms. The mass of one atom is a simple division.\n\n\\[ \\text{Mass of one atom} = \\frac{\\text{Molar Mass}}{N_A} \\]\n\n\\[ m = \\frac{27\\text{ g/mole}}{6.02 \\times 10^{23}\\text{ atoms/mole}} \\]\n\n\\[ m = 4.5 \\times 10^{-23}\\text{ g/atom} \\]\n\nThe mole unit cancels, leaving grams per atom. The result is a number so small that it cannot be felt directly, but it represents the mass of one aluminium atom.\n\nThe reciprocal relationship is important: divide by \\(6.02 \\times 10^{23}\\) to go from molar mass to atomic mass, multiply to go the other way. The magnitude of the result is roughly the molar mass with the exponent shifted to the negative 23.\n\nWhen a problem asks for atomic mass from molar mass, divide by Avogadro's number. When it asks for total mass from number of atoms, multiply.",
