    explanation: "## One Number Is Enough\n\nRead a thermometer and see \\(25^\\circ\\text{C}\\). That number and a unit describe the temperature completely, with no arrow, no compass, and no direction required.\n\nA **scalar quantity** has magnitude only and no direction. Scalars obey ordinary algebra, so they can be added, multiplied, and divided like any ordinary number.\n\nA scalar is purely a numerical value and a unit:\n\\[ \\text{Scalar} = \\text{Magnitude} \\]\n\nTemperature, mass, distance, speed, work, and electric current all behave this way. Point north and the temperature does not change.\n\nWhen a number plus a unit fully describes a quantity, it is scalar. If direction is needed to make the sentence true, the quantity is not scalar.",
