    correct: 3,
    explanation: "## Where You Are\n\nStand in a car park with a map. Before you move, you need to know where you already are. That is what a position vector records.\n\nA **position vector** describes the location of a point relative to a chosen origin.\n\\[ \\mathbf{r} = x\\hat{i} + y\\hat{j} + z\\hat{k} \\]\n\nIf the origin is \\(O\\) and the point is \\(P\\), the position vector is written \\(\\overrightarrow{OP}\\). The values of x, y, and z directly give the point's location in space.\n\nDisplacement is a change in position. Velocity is how fast position changes. The position vector itself is the raw coordinate, before any motion has occurred.\n\nWhen you start a problem in two or three dimensions, the first thing to write down is the position vector. Everything else is built on top of it.",
