    explanation: "## A Zero That Means Ninety Degrees\n\nThe dot product answers a geometric question: how much of one vector points along the other? A zero answer means the two have no component in common along either direction.\n\n\\[ \\mathbf{A} \\cdot \\mathbf{B} = AB\\cos\\theta = 0 \\]\n\nSince neither \\(\\mathbf{A}\\) nor \\(\\mathbf{B}\\) is zero, both \\(A\\) and \\(B\\) are nonzero. Setting the product to zero forces:\n\\[ \\cos\\theta = 0 \\]\n\nThe only angles in the standard range with a zero cosine are \\(90^\\circ\\) and \\(270^\\circ\\). Both describe perpendicular directions.\n\nThe perpendicularity test is one of the most useful consequences of the dot product. Given two vectors in component form, computing \\(\\mathbf{A} \\cdot \\mathbf{B}\\) tells you immediately whether they meet at right angles, without drawing a diagram.\n\nWhen a problem asks whether two vectors are perpendicular, compute the dot product. A zero result is a definitive yes; a nonzero result is a definitive no.",
