    correct: 2,
    explanation: "## The Trail the Particle Leaves\n\nA hiker crosses a valley along a winding trail. On a map, the trail is a line showing every point the hiker stepped on. That line is what physics calls the path.\n\nThe **path** of a particle is the line joining all the positions the particle passes through during its motion. It records the route, not just the destination.\n\nThere is no equation for this geometric definition. The path is simply the set of all coordinates (x, y, z) the particle occupies over time.\n\nIf you trace the motion of an object with a pen on a piece of paper, the ink line left behind is the path. The straight arrow drawn from the starting dot to the ending dot is the displacement.\n\nThe distinction from displacement is important. Displacement connects the starting point to the ending point with a straight arrow. The path is the full trail between them, and in a curved journey the path can be much longer than the displacement.\n\nWhen a problem asks about the route taken, it is asking about the path. When it asks about the straight-line distance from start to finish, it is asking about displacement."
