    explanation: "## A Surface Is a Plane\n\nA boat on a lake can move north, south, east, or west. Its position on the water is fixed by two coordinates, one for each direction along the lake's surface. That makes its motion two-dimensional.\n\n**Two-dimensional motion** occurs when the object moves within a plane. Two coordinates describe its position, and no third coordinate is involved in the motion being studied.\n\nThe position vector is \\(\\mathbf{r} = x\\hat{i} + y\\hat{j}\\). The coordinates x and y change, but z remains constant.\n\nIf the object is confined to a flat surface (like the lake), it is 2D. If it can climb or dive (like a bird or plane), it is 3D. If it is on a single track, it is 1D.\n\nWhen reading a problem, ask which coordinates are necessary. If the object stays on a surface, the motion is planar. If it can rise and fall as well, the motion is spatial.\n\nWhen you see a motion described in an exam, count how many coordinates change. If it stays on a flat surface, it's 2D."
