    explanation: "## Motion in Space\n\nAn aeroplane in flight is not confined to a straight line or a flat surface. It can change altitude, fly north-south, and bank east-west, all at once. Three coordinates are needed to describe where it is at any moment.\n\n**Three-dimensional motion** occurs when the object moves through space, requiring three coordinates to specify its position. The object can move up or down as well as across and along, so all three dimensions of space are involved.\n\nThe position vector is \\(\\mathbf{r} = x\\hat{i} + y\\hat{j} + z\\hat{k}\\). All three coordinates (x, y, z) can change independently.\n\nAn aeroplane changes x, y, and z. A car on a road changes only one. A falling object changes only the vertical coordinate. Only the aeroplane requires the full 3D treatment.\n\nWhen a problem involves an object that can change altitude, its motion is usually three-dimensional. If altitude does not change, the motion drops to two dimensions or fewer.\n\nWhen a problem mentions an object flying, swimming, or diving freely through space, assume three-dimensional motion unless stated otherwise."
