    explanation: "## The Right Side Is Positive\n\nA number line carries a simple convention. One side of the origin carries positive numbers, the other carries negatives. Getting the convention right matters because the sign carries direction.\n\nAlong a horizontal number line, positions to the right of the origin are taken as **positive**. Positions to the left are negative. The origin itself has position zero.\n\nThe convention is \\(x > 0\\) for positions to the right of O, and \\(x < 0\\) for positions to the left.\n\nIf you move 5 units to the right of O, your position is \\(+5\\). If you move 5 units to the left, your position is \\(-5\\). The origin itself is \\(0\\).\n\nFor vertical motion, the same logic applies with a vertical axis. Positions above the origin are positive; positions below are negative.\n\nThe convention is not physics, it is bookkeeping. But every displacement, velocity, and acceleration inherits the same sign convention, so getting the sign right at the start saves confusion later."
