    correct: 3,
    explanation: "## A Shortcut Is Never Longer Than the Road\n\nA winding mountain road can carry a driver many kilometres, while a straight tunnel through the mountain might be only a fraction of that. The straight path from start to end is never longer than the winding one.\n\nThe same idea applies to distance and displacement. Distance measures the path length, which counts every detour. Displacement measures the straight-line shift from start to end, which is the shortest possible path between two points.\n\nThe fundamental inequality is \\(|\\Delta \\mathbf{r}| \\leq d\\). The magnitude of displacement is less than or equal to the distance.\n\nIf a car travels 10 km along a curve but ends up only 6 km from the start, the distance is 10 km and the displacement magnitude is 6 km. The straight-line shortcut (6) is shorter than the road (10).\n\nBecause the straight-line path is a minimum, the magnitude of displacement never exceeds the distance travelled. The two are equal only when the motion is in one direction without any reversal.\n\nWhen a problem gives both quantities, compare them. If displacement magnitude is larger than distance, an error has been made somewhere. That single check catches many mistakes in kinematics problems."
