    explanation: "## Around the Loop and Back\n\nA runner circles a track and ends where they started. The path has length equal to the circumference, but the starting and ending positions are identical. That is the whole story of the difference between distance and displacement.\n\nDistance uses the total path length: \\(d = 400\\text{ m}\\).\nDisplacement uses the change in position: \\(\\Delta x = x_{\\text{final}} - x_{\\text{initial}}\\).\n\nDistance is simply the circumference: \\(d = 400\\text{ m}\\).\nDisplacement is the starting position subtracted from the ending position: \\(\\Delta x = 0 - 0 = 0\\text{ m}\\).\n\nThe distance tells you how much work the legs did. The displacement tells you how far the body ended up from where it began. In a closed loop, those two numbers are very different.\n\nWhen an exam question involves motion around a loop or a round trip, watch out. Distance is not zero even though displacement is. The examiner is testing if you can keep them apart."
