    correct: 1,
    explanation: "## One Carries Direction, One Does Not\n\nA cyclist might travel 20 km/h on average along a winding road, but the net shift from start to finish could be only 5 km to the east. Both numbers describe the trip, but only one of them carries a direction.\n\n**Average speed** is a scalar. It is total distance divided by total time, with no directional component.\n\nAverage speed: \\(v_{avg} = d / t\\).\nAverage velocity: \\(\\mathbf{v}_{avg} = \\Delta \\mathbf{r} / t\\).\n\nThe key difference is that average velocity uses the displacement vector.\n\nIn the cyclist's case, the speed would be high (covering a long winding road in a given time), while the velocity magnitude would be low (small straight-line displacement in that same time). They are fundamentally different quantities.\n\nThe two share units (\\(\\text{m/s}\\)) and dimension [LT⁻¹]. They differ in whether direction is part of the answer. If the two are equal in magnitude, motion has been strictly one-way along a straight line, which is a special case rather than the rule.\n\nWhen a problem asks for a rate of travel, check which quantity is wanted. If the answer should carry direction, the problem is asking for velocity. If not, it is asking for speed."
