    correct: 3,
    explanation: "## Constant Acceleration, Curved Path\n\nPush a ball sideways off a table. It curves downward toward the floor, yet the acceleration on it is constant and equal to \\(g\\), pointing straight down. The path is a parabola, but the acceleration vector does not change.\n\n**Uniform acceleration** means the acceleration vector is constant in both magnitude and direction. This does *not* imply the object moves in a straight line.\n\nProjectile motion uses \\(\\mathbf{a} = -g\\hat{j}\\) throughout the flight, regardless of the path shape.\n\nBraking on a straight road and free fall from rest both keep the path straight. Those are one-dimensional cases. A projectile launched at an angle moves along a curve while experiencing the constant downward acceleration of gravity.\n\nProjectile motion is the standard case. Throughout the flight, gravity exerts the same downward force, so acceleration is constant. The velocity vector changes direction continuously, and the path is a curve.\n\nWhen a problem says 'uniform acceleration', ask what direction that acceleration points. If it does not match the direction of motion, the path will curve, and the problem becomes a two-dimensional one."
