    explanation: "## Stopping Gradually\n\nA car coasts to a halt with the brakes applied. The initial velocity is known, the final velocity is zero, and the time to stop is known. Retardation is the magnitude of the negative acceleration.\n\nFirst, convert units: \\(54\\text{ km/h} = 15\\text{ m/s}\\), and \\(1.5\\text{ min} = 90\\text{ s}\\).\nThen apply: \\(a = \\frac{v - v_{0}}{t}\\).\n\n\\[ a = \\frac{0 - 15}{90} \\]\n\n\\[ a = -0.167\\text{ m/s}^{2} \\]\nThe negative sign indicates that the acceleration points opposite to the initial velocity, which is why the car slows. The **retardation** is the magnitude of this deceleration, \\(0.167\\text{ m/s}^{2}\\).\n\nFor a car to slow this gently from highway speed takes over a minute, which is much more comfortable than typical braking. Real braking usually happens in a few seconds, giving a retardation closer to \\(5\\text{ m/s}^{2}\\).\n\nWhen a problem gives speed in km/h and time in minutes, convert both before dividing. Skipping the conversions gives a number that looks reasonable but is off by an enormous factor."
