    explanation: "## Distance From Velocity and Acceleration\n\nGiven an initial velocity, a final velocity of zero, and a deceleration, the displacement can be computed without knowing the time.\n\nThe three kinematic equations each omit one variable. Here time is not given, so use the position-velocity relation:\n\\[ v^{2} = v_{0}^{2} + 2as \\]\n\n\\[ 0 = (15)^{2} + 2(-0.167)s \\]\n\n\\[ 0 = 225 - 0.334s \\]\n\\[ 0.334s = 225 \\]\n\\[ s = \\frac{225}{0.334} \\approx 674\\text{ m} \\]\nRounded to three significant figures, the distance is \\(675\\text{ m}\\).\n\nThe answer is large because the car is braking gently. A real braking scenario stops the car in tens of metres, not hundreds, because the retardation is much larger. The physics is identical, only the numbers change.\n\nWhen time is not given and cannot be easily computed, the position-velocity relation \\(v^{2} = v_{0}^{2} + 2as\\) is the fastest route to the answer. It connects the four quantities the problem actually mentions."
