    explanation: "## Two Trains, Opposite Ways\n\nSet north as positive. Train A moves north at \\(+15\\text{ m/s}\\). Train B moves south at \\(-25\\text{ m/s}\\). The negative sign is not decoration, it is the direction encoded as a number.\n\n\\[ v_{B/A} = v_{B} - v_{A} \\]\n\n\\[ v_{B/A} = (-25) - (+15) \\]\n\n\\[ v_{B/A} = -40\\text{ m/s} \\]\nThe sign of the result is negative, so B is moving south relative to A. The magnitude is \\(40\\text{ m/s}\\).\n\nWhen two objects move in opposite directions, the relative speed is the sum of the two speeds. That is why the result is \\(40\\) rather than \\(10\\). If both trains moved north at these speeds, the relative velocity would be \\(15 - 25 = -10\\text{ m/s}\\), a much smaller value.\n\nWhen a problem involves opposite directions, treat the direction as a sign and subtract algebraically. Summing the magnitudes only works when the two objects move along the same line in opposite directions. If they are perpendicular, the addition uses Pythagoras, not arithmetic."
