    explanation: "## The Difficulty of Stopping a Moving Body\n\nA cyclist rolling slowly is easy to stop with one hand. A truck rolling slowly is not, even though the speed is the same. The difference is mass. Momentum captures how the mass and the velocity work together.\n\nLinear momentum is defined as the product of mass and linear velocity:\n\\[ \\mathbf{p} = m\\mathbf{v} \\]\n\nIt is a vector, pointing in the same direction as the velocity. Its SI unit is \\(\\text{kg} \\cdot \\text{m/s}\\). Velocity describes how fast the object moves. Momentum describes how hard the object is to stop.\n\nSame speed, more mass, more momentum, harder to stop. That difference explains why a bullet has high momentum despite its tiny mass, and why a walking elephant has high momentum despite its modest speed.\n\nWhen a problem involves collisions, explosions, or impulsive forces, work in momentum. The rate of change of momentum is the force, and changes in momentum across an interaction are governed by conservation laws.",
