    correct: 1,
    explanation: "## Force as the Rate of Momentum Change\n\nThe original form of Newton's Second Law is not \\(F = ma\\). It is a statement about how fast momentum changes. For constant mass, the two are equivalent. For variable mass, only the momentum form is correct.\n\nThe momentum form:\n\\[ F = \\frac{dp}{dt} \\]\n\nSince \\(p = mv\\), the derivative is:\n\\[ \\frac{dp}{dt} = \\frac{d(mv)}{dt} = m\\frac{dv}{dt} + v\\frac{dm}{dt} \\]\nFor constant mass, the second term vanishes, leaving:\n\\[ F = m\\frac{dv}{dt} = ma \\]\n\nThe two forms are the same law. The momentum form is the deeper one, because it survives when mass changes. Rockets, for example, lose mass as they burn fuel, and the \\(ma\\) form is no longer sufficient.\n\nWhen a problem involves constant mass, \\(F = ma\\) is quicker. When a problem involves a system whose mass changes during the process, return to \\(F = dp/dt\\).",
