    correct: 1,
    explanation: "## Opposite in Direction, Equal in Size\n\nThe action and reaction are two vectors. Their magnitudes are equal, but their directions are opposite. Vector notation captures both properties in one equation.\n\nThe Third Law in vector form:\n\\[ \\mathbf{F}_{1} = -\\mathbf{F}_{2} \\]\n\nThe minus sign is what makes this a vector statement rather than a scalar one. Written without vectors, the equation would only say that the magnitudes match, losing the direction information. Written with the minus sign, it captures the full fact.\n\nAn alternate statement of the same law says that the two forces are equal in magnitude and opposite in direction:\n\\[ \\left|\\mathbf{F}_{1}\\right| = \\left|\\mathbf{F}_{2}\\right| \\quad \\text{and} \\quad \\mathbf{F}_{1} = -\\mathbf{F}_{2} \\]\n\nBoth forms say the same thing. The vector form is compact and captures the direction without needing a separate statement about it.\n\nWhen writing out an action-reaction pair, name the two bodies. The force on body A from body B equals minus the force on body B from body A.",
