    explanation: "## The Floor Pushing Back\n\nStand on a bathroom scale. The scale does not sink under your feet because the floor and the scale push back. That upward push is the normal force, and it appears whenever two surfaces meet.\n\nThe **normal force** is a contact force exerted by a surface on a body, directed perpendicular to that surface. The word 'normal' here means perpendicular, not 'ordinary'.\n\nFor a block resting on a horizontal table at rest:\n\\[ N = mg \\]\nOn an inclined plane:\n\\[ N = mg\\cos\\theta \\]\n\nwhere \\(\\theta\\) is the angle of the incline from the horizontal. The perpendicular relationship makes the cosine the right function, not the sine.\n\nThe normal force is not always equal to \\(mg\\). If another force presses the block into the surface or lifts it away, the normal force changes accordingly. The value comes from the equilibrium or motion condition in the perpendicular direction, not from a formula on its own.\n\nWhen a problem asks for the normal force, set up Newton's Second Law perpendicular to the surface.",
