    correct: 1,
    explanation: "## Balanced Forces on a Level Surface\n\nA book lies flat on a desk. It does not sink, and it does not fly up. Something must be balancing it, and that something is the normal force.\n\nThe two forces in the vertical direction are the weight acting downward and the normal force acting upward. For the book to be at rest, these must balance.\n\n\\[ N - mg = 0 \\]\n\\[ N = mg \\]\n\nIn vector form:\n\\[ \\mathbf{W} = -\\mathbf{N} \\quad \\text{and} \\quad \\left|\\mathbf{W}\\right| = \\left|\\mathbf{N}\\right| \\]\n\nThe two vectors have the same magnitude and opposite directions. If either changed, the block would accelerate, either down (if the normal became smaller) or up (if the normal became larger).\n\nThe equilibrium condition does not mean the two forces are a Third Law pair. Both act on the same body, and that is why they cancel. A Third Law pair requires the two forces to act on two different bodies.\n\nWhen a body is at rest on a horizontal surface with no other vertical forces, the normal force equals the weight.",
