    options: [
      "\\(f_{s} = \\mu_{s}N\\)",
      "\\(f_{s} = \\mu_{k}N\\)",
      "\\(f_{s} = \\mu_{s}g\\)",
      "\\(f_{s} = \\dfrac{\\mu_{s}}{N}\\)"
    ],
