    correct: 2,
    explanation: "## Harder to Start Than to Keep Going\n\nOnce you get a heavy box sliding, it suddenly feels easier to keep it moving. The force you need drops. This everyday experience reflects a fact about friction coefficients: kinetic friction is smaller than the maximum static friction.\n\nThe relationship is:\n\\[ \\mu_{k} < \\mu_{s} \\]\nfor the same pair of surfaces.\n\nThe explanation is in the bonding. When two surfaces are at rest, the contact points have time to lock together, and breaking them requires effort. Once sliding, the surfaces are constantly forming and breaking new bonds, and each bond lasts only briefly, so the average resistance is lower.\n\nThe friction-versus-applied-force graph captures this. As applied force increases, friction rises along the static line until it reaches \\(\\mu_{s}N\\). Then the object starts to slide, friction drops to \\(\\mu_{k}N\\), and stays roughly constant after that. The drop from \\(\\mu_{s}\\) to \\(\\mu_{k}\\) is visible in the graph as a step.\n\nWhen a problem involves both starting and keeping a motion going, expect two different friction values.",
