    correct: 0,
    explanation: "## Standing Still Inside a Lift\n\nA stationary lift is no different from a room in a building. The floor supports the body, and the support equals the weight.\n\nThe body inside experiences two forces: weight \\(mg\\) pointing down and normal force \\(N\\) pointing up. With the lift at rest, the acceleration is zero.\n\n\\[ \\sum F_{y} = ma \\]\n\\[ N - mg = 0 \\]\n\n\\[ N = mg \\]\n\nThe apparent weight equals the actual weight. Nothing has changed about the body, the floor, or the gravitational field.\n\nThis baseline case is worth remembering because it is the reference for all the other cases. When the lift accelerates up, \\(N\\) grows above \\(mg\\). When it accelerates down, \\(N\\) falls below \\(mg\\). When the lift is in free fall, \\(N\\) drops to zero. The stationary case is the anchor.\n\nWhen a problem asks for apparent weight, ask what the lift is doing.",
