    explanation: "## Counting Atomic Oscillations\n\nAn atomic clock does not tick in the mechanical sense. Instead, it counts the oscillations of a specific transition in a specific atom, and the count is reproducible to extraordinary precision.\n\nSince 1967, the second has been defined by the **cesium-133 isotope**.\n\n\\[ 1\\text{ s} = 9,192,631,770 \\text{ oscillations of Cesium-133} \\]\n\nOne of the transitions between two energy levels in its ground state oscillates at a specific frequency, and this frequency defines the second. The choice of atom is not arbitrary; Cesium-133 was selected because its transition is sharply defined and stable.\n\nThe transition from astronomical time to atomic time was driven by the same logic as the metre redefinition: physical constants and atomic properties are reproducible anywhere, astronomical observations are not.\n\nWhen you see a standard based on atomic properties, remember that the precision comes from the reproducibility of quantum transitions.",
