    explanation: "## The Kilogram in a Jar\n\nFor most of the twentieth century, the definitive kilogram was not a definition in terms of constants. It was a physical object, a cylinder of metal kept under a double bell jar in a room outside Paris.\n\nUntil 2019, the standard kilogram was a **platinum-iridium cylinder**, \\(3.9\\text{ cm}\\) in diameter and \\(3.9\\text{ cm}\\) in height.\n\n\\[ V = \\pi r^2 h \\]\n\\[ m = \\rho V \\]\n\nThe alloy was chosen for stability, because it resists corrosion and thermal expansion better than pure platinum. \n\nAccurate copies of this artefact were distributed to standardising laboratories around the world. Any lab wanting to calibrate a mass had to trace its mass back, ultimately, to that single cylinder in France.\n\nIn 2019, the kilogram was redefined in terms of Planck's constant. The change followed the same pattern as the metre and the second: a physical artefact replaced by a reproducible natural constant.",
