    explanation: "## A Single Location for the World's Kilogram\n\nAn artefact standard has to live somewhere. If the object can be moved, it can be damaged in transit, stolen, or substituted. For the kilogram, the choice was made to keep the artefact in one place under controlled conditions.\n\nUntil 2019, the international prototype kilogram was kept at the **International Bureau of Weights and Measures (BIPM), near Paris**.\n\nThis is a geographical fact regarding standardisation.\n\nEvery country's standard kilogram was a carefully calibrated copy, and each copy could be traced back to the artefact in France. The location was chosen for stability rather than prestige.\n\nThe switch to a constant-based standard in 2019 was partly motivated by wanting to remove the dependency on a single physical location. Any lab with the right equipment can now realise a kilogram from Planck's constant.\n\nWhen you read about standard artefacts, remember that their primary weakness is their physical nature. They can be lost, damaged, or altered.",
