    explanation: "## Every Term Must Match Velocity\n\nThe velocity \\(v\\) has dimension \\(LT^{-1}\\). The equation \\(v = at^{2} + bt + c\\) means every term on the right must also carry \\(LT^{-1}\\), or the equation would be meaningless.\n\n\\[ [v] = [a t^2] = [b t] = [c] \\]\n\nMatch each term to \\(LT^{-1}\\):\n\\[ [a] \\cdot T^{2} = LT^{-1} \\]\n\\[ [b] \\cdot T = LT^{-1} \\]\n\\[ [c] = LT^{-1} \\]\n\n\\[ [a] = LT^{-3} \\]\n\\[ [b] = LT^{-2} \\]\n\\[ [c] = LT^{-1} \\]\n\nThe pattern is that as the power of \\(t\\) increases, the time exponent on the coefficient becomes more negative. The square term needs the strongest correction to reach \\(LT^{-1}\\), and the constant term needs no correction.\n\nWhen you dimensionally analyse a polynomial equation, treat each term separately. Divide the target dimension by the power of \\(t\\) in that term, and the result is the coefficient's dimension.",
    status: "approved"
