    correct: 1,
    explanation: "## A Balanced Scale\n\nAn equation that mixes apples and oranges is not wrong because of the answer it gives. It is wrong because the two sides do not describe the same kind of quantity. The scale does not balance.\n\nThe **principle of homogeneity** states that in a valid physical equation, **all terms on both sides must have the same dimensions**.\n\nFor an equation \\(A + B = C\\), the principle requires:\n\\[ [A] = [B] = [C] \\]\n\nIf the left side is a length \\([L]\\) and the right side is a time \\([T]\\), the equation is not asserting an equality of values; it is asserting an equality of kinds, and the kinds do not match.\n\nThis does not forbid multiplication and division across dimensions. \\(F = ma\\) multiplies mass and acceleration to produce force, and that is homogeneous because both sides have dimension \\(MLT^{-2}\\). The principle only rules out adding terms of different dimensions.\n\nWhen you check an equation for correctness, check that every term on both sides has the same dimension. If a single term breaks the pattern, the equation is not valid.",
