    correct: 2,
    explanation: "## Deriving a Formula From Dimensions\n\nSuppose the only information you have is that the acceleration depends on \\(v\\) and \\(r\\). Dimensional analysis can tell you which combination produces the correct dimension.\n\nAssume the form \\(a = k \\cdot v^{n} \\cdot r^{m}\\). The dimension of acceleration is \\(LT^{-2}\\).\n\n\\[ [a] = [v]^n [r]^m \\]\n\\[ LT^{-2} = (LT^{-1})^n L^m \\]\n\\[ LT^{-2} = L^{n+m}T^{-n} \\]\n\nMatch exponents:\n\\[ -n = -2 \\implies n = 2 \\]\n\\[ n + m = 1 \\implies 2 + m = 1 \\implies m = -1 \\]\n\nSo the form is \\(a = k\\frac{v^{2}}{r}\\).\n\nThe derivation does not give the constant \\(k\\). Dimensional analysis cannot do that; it only produces the algebraic form. For a circle in uniform motion, the constant happens to be \\(1\\).\n\nWhen a problem tells you what a quantity depends on and asks for the form, set up the power relationship and match dimensions. The exponents fall out of the algebra.",
