    correct: 0,
    explanation: "## A Necessary Check, Not a Sufficient One\n\nDimensional analysis confirmed that every term in the equation has dimension \\(L\\). That is a strong signal. It is not a proof of correctness.\n\nThe dimensional check verifies the exponent balance:\n\\[ [s] = [ut] = [at^2] \\]\n\\[ L = (LT^{-1})(T) = (LT^{-2})(T^2) \\]\n\nThe check works perfectly. However, it only verifies that the equation has the right **kind** of quantity on both sides. It cannot verify the numerical coefficients, the signs, or the physical assumptions behind the formula.\n\nFor \\(s = ut + \\frac{1}{2}at^{2}\\), the dimensional check confirms that both terms are lengths. It does not confirm that the coefficient is exactly \\(\\frac{1}{2}\\) rather than 2 or \\(\\frac{1}{4}\\).\n\nWhen you use dimensional analysis, treat it as a fast screening tool. If it fails, the equation is wrong. If it passes, the equation is a candidate for correctness and needs further verification.",
