    explanation: "## The Digits You Trust\n\nA student writes down a length as \\(4.330\\text{ m}\\). The final zero on the end is not decoration. It says: this digit matters, this digit was measured, this digit is part of what I am confident about.\n\nThe **significant figures** of a measurement are the digits in which you have confidence.\n\nThere is no calculation formula, but the rule of counting is based on the measurement's resolution.\n\nWhen a stopwatch is stated to read \\(4.3\\text{ s}\\) rather than \\(4.30\\text{ s}\\), the difference is not the value (both are approximately the same time) but the trust you can place in the final digit. The \\(4.30\\) claims more confidence than the \\(4.3\\).\n\nWhen you read a measurement, count the significant figures before you record the value. The count tells the reader how much to trust the trailing digits. Without the count, a student might carry a low-precision measurement into a high-precision calculation and lose the meaning of the answer.",
