    correct: 3,
    explanation: "## Three Trailing Zeros All Count\n\nA measurement written as \\(343.000\\) is making a precision claim. The three trailing zeros are not padding; they are digits the measurement trusts.\n\nCount all non-zero digits, plus zeros between non-zeros, plus trailing zeros after a decimal point.\n\nCount them. The 3, 4, and 3 are non-zero digits, so three significant figures so far. The decimal point opens the trailing-zero zone. All three zeros after the decimal point are trailing zeros, and trailing zeros after a decimal point are significant.\n\\[ 3, 4, 3, 0, 0, 0 \\rightarrow \\text{6 digits} \\]\n\nThe total is six significant figures. The final zero is as significant as the first 3.\n\nA shorter number like \\(343\\) would have three significant figures. The measurement \\(343.000\\) is asserting that the value is trusted to three decimal places, which is why all three trailing zeros count. When a number carries a decimal point and zeros follow it, count them.",
