    explanation: "## When the Number Is Already Close\n\nRounding is a decision about how to represent a value with fewer digits. When the digit being dropped is small (less than 5), the value is already close to the truncated form, and no adjustment is needed.\n\nIf the digit to be dropped is **less than 5**, the preceding digit is **left unchanged**.\n\nConsider \\(7.82\\). We want to round to one decimal place.\nThe dropped digit is 2.\nSince \\(2 < 5\\), the preceding digit (8) remains 8.\n\n\\(7.82\\) rounds to \\(7.8\\), because the digit being dropped is 2, and 7.8 is closer to 7.82 than 7.9 is.\n\nThe value being dropped is thrown away, not added to the preceding digit. The only time a rounding changes the preceding digit is when the dropped digit is 5 or higher.\n\nWhen you round a number, ask whether the truncated form is closer to the original than the raised form. If it is, leave the preceding digit alone.",
