    explanation: "## Climbing to the Closer Number\n\nA value like \\(6.87\\) is closer to \\(6.9\\) than to \\(6.8\\). The decimal 0.87 is more than halfway between 0.8 and 0.9, so the correct rounded form moves up.\n\nIf the digit to be dropped is **more than 5**, the preceding digit is **raised by one**.\n\nConsider \\(6.87\\). We want to round to one decimal place.\nThe dropped digit is 7.\nSince \\(7 > 5\\), the preceding digit (8) is raised to 9.\n\n\\(6.87\\) rounds to \\(6.9\\), and \\(12.78\\) rounds to \\(12.8\\). The dropped digit is greater than the midpoint, so the closest representable value is the one above.\n\nThe rule is the mirror image of the previous case. When the discarded part is small (less than 5), the truncated form wins. When it is larger (more than 5), the raised form wins.\n\nWhen you round a number, read the digit being dropped before deciding. Rounding is not a habit; it is a decision made per digit.",
