    correct: 0,
    explanation: "## Relative Errors Add Under Multiplication\n\nMultiplying two quantities is like chaining two uncertain measurements. The percentage error of the product is roughly the sum of the percentage errors of the inputs.\n\nFor \\(x = a \\times b\\), the maximum relative error in \\(x\\) is:\n\\[ \\frac{\\Delta x}{x} = \\frac{\\Delta a}{a} + \\frac{\\Delta b}{b} \\]\n\nIf the error in \\(a\\) is 2% and the error in \\(b\\) is 3%, we substitute:\n\\[ \\frac{\\Delta x}{x} = 2\\% + 3\\% \\]\n\n\\[ \\frac{\\Delta x}{x} = 5\\% \\]\n\nThe pattern is that relative errors **add** under multiplication and division, while absolute errors add under addition and subtraction. The two rules look similar but apply to different situations. Mixing them up is a common error.\n\nA 2% error in one factor and a 3% error in another produce a product with a 5% error, not a 6% error (as multiplying percentages would give) and not a 1% error (as subtracting would give).",
