    explanation: "## Percentage Errors in a Ratio\n\nVelocity is displacement divided by time. Both measurements carry errors. The error in the velocity is not the error in either measurement; it is the accumulated error from both, propagated through the division.\n\n**The formula.**\nVelocity \\(v = \\frac{s}{t}\\). The relative error in \\(v\\) is the sum of the relative errors in \\(s\\) and in \\(t\\).\n\\[ \\frac{\\Delta v}{v} = \\frac{\\Delta s}{s} + \\frac{\\Delta t}{t} \\]\n\n**Substituting.**\n\\[ \\frac{\\Delta s}{s} = \\frac{5}{200} = 0.025 = 2.5\\% \\]\n\\[ \\frac{\\Delta t}{t} = \\frac{0.2}{20} = 0.01 = 1.0\\% \\]\n\n**Evaluating.**\nThe total relative error is the sum: \\(2.5\\% + 1.0\\% = 3.5\\%\\).\n\nNotice that the errors are combined by addition, not by multiplication. A student who multiplied the percentages would get \\(2.5 \\times 1.0 = 2.5\\%\\), missing the accumulation. A student who subtracted would get 1.5%, understating it.\n\nWhen a quantity is a quotient of two measured values, add their percent errors. The rule does not depend on which is in the numerator.",
