    correct: 1,
    explanation: "## Rounding Below One\n\nThe same rule applies to numbers smaller than one. The leading digit's size determines whether the exponent moves up or stays the same. What changes is the direction the exponent moves.\n\n\\[ N = 9.1 \\times 10^{-31} \\]\n\nThe leading digit of \\(9.1 \\times 10^{-31}\\) is 9.1, which is at least 5. The mantissa rounds up and the exponent increases by one.\n\n\\[ O(N) = 10^{-30}\\text{ kg} \\]\n\nNotice the counterintuitive element: increasing the exponent from \\(-31\\) to \\(-30\\) makes the number larger in absolute value, because \\(10^{-30} > 10^{-31}\\). Rounding up here means rounding toward the larger magnitude, which is what the leading digit calls for.\n\nThe rule does not care whether the exponent is positive or negative. The leading digit decides the direction, and the exponent follows. When the leading digit is below 5, keep the exponent; when it is 5 or above, raise the exponent by one.",
    status: "approved"
