    explanation: "## Scanning a List for a Slip\n\nLook at each item in a candidate list and ask one question: would a sign, arrow, or compass be needed to make this value correct? If yes, the item is not scalar.\n\n\\[ \\text{Scalar List} = \\text{Only items with magnitude} \\]\n\nMass is a number of kilograms. Temperature is a number of kelvin. Work is a scalar measure of energy transfer. Speed is distance divided by time, with no direction attached. Each is fully described by a number and a unit.\n\nForce, velocity, acceleration, and displacement all carry direction and belong to the vector class. Any of them in a candidate list makes the whole list non-scalar.\n\nWhen a list is offered in an exam, read to the end before answering. A single vector at position four ruins a list that otherwise looks clean.",
