    explanation: "## Ink That Signals Direction\n\nBefore typing fonts existed, scribes needed a way to mark a vector without drawing an arrow. Bold type became the answer in printed text.\n\n\\[ \\text{Vector} \\rightarrow \\mathbf{A} \\text{ or } \\vec{A} \\]\n\\[ \\text{Scalar Magnitude} \\rightarrow A \\]\n\nIn print, a vector is written in **bold**, for example \\(\\mathbf{A}\\) or \\(\\mathbf{a}\\). In handwriting, the same idea is carried by an arrow: \\(\\vec{A}\\) or \\(\\vec{a}\\). The magnitude drops both marks, so \\(A\\) or \\(a\\) alone means the size, not the vector.\n\nThese are shorthand conventions, not physics, but they have to be read accurately. The bold mark is the reader's signal that a directed quantity is on the page. When a textbook uses one style, expect the other in another book.",
