    correct: 0,
    explanation: "## Same Arrow, Reversed\n\nThe negative of a vector is the same arrow flipped, with its length untouched.\n\n\\[ |-\\mathbf{A}| = |\\mathbf{A}| \\]\n\\[ \\text{direction}(-\\mathbf{A}) = -\\text{direction}(\\mathbf{A}) \\]\n\nWritten as \\(-\\mathbf{A}\\), the negative vector has **the same magnitude** as \\(\\mathbf{A}\\) but **the opposite direction**. The minus sign does not touch the length; it only reverses the arrow.\n\nThis matters because subtraction is defined through it. The expression \\(\\mathbf{A} - \\mathbf{B}\\) means \\(\\mathbf{A} + (-\\mathbf{B})\\). Reverse the arrow of the vector being subtracted, then add as usual.\n\nWhen a minus sign appears in front of a vector, read it as \"reverse the arrow,\" not as \"make it smaller.\"",
    status: "approved"
