    explanation: "## A Direction, Stripped of Size\n\nA unit vector is what remains of a vector after you throw away its length and keep only the direction it points.\n\n\\[ |\\hat{n}| = 1 \\]\n\nA **unit vector** is dimensionless, has magnitude exactly one, and identifies a direction. Because it is dimensionless, it carries no metres, no newtons, and no seconds.\n\nConsider the difference between a force of \\(50\\text{ N}\\) due north and a force of \\(5\\text{ N}\\) due north. Different magnitudes, same direction. The unit vector that captures that shared direction is the same for both: north.\n\nWhen a problem asks you to describe a direction on its own, a unit vector is the right tool. It says \"this way\" without saying \"this much.\"",
