    correct: 2,
    explanation: "## The Vector With No Arrow\n\nWalk five steps east and then five steps west. The displacement is zero, but it is still a displacement, not the absence of one.\n\nA **zero vector**, also called a null vector, has magnitude zero and is written \\(\\mathbf{0}\\).\n\\[ |\\mathbf{0}| = 0 \\]\n\nIts direction is undefined because there is nothing to point at. The null vector is the identity for addition:\n\\[ \\mathbf{A} + \\mathbf{0} = \\mathbf{A} \\]\n\nIt is also what you get when adding a vector to its own negative, since \\(\\mathbf{A} + (-\\mathbf{A}) = \\mathbf{0}\\).\n\nWhen a calculation returns zero for a vector quantity, write \\(\\mathbf{0}\\), not scalar zero. The distinction matters in vector algebra, because a scalar zero cannot be added to a vector, but a null vector can.",
