    explanation: "## Placing the Arrows End to End\n\nThe triangle method stacks two arrows so the tip of one touches the tail of the next. This layout is called head-to-tail.\n\n\\[ \\mathbf{R} = \\mathbf{A} + \\mathbf{B} \\]\n\nThe procedure:\n1. Draw \\(\\mathbf{A}\\) anywhere on the page.\n2. Draw \\(\\mathbf{B}\\) so its tail sits at the head of \\(\\mathbf{A}\\).\n3. Draw \\(\\mathbf{R}\\) from the tail of \\(\\mathbf{A}\\) to the head of \\(\\mathbf{B}\\).\n\nThe resultant closes the triangle from the very first tail to the very last head. Swapping the drawing order does not change the resultant, but the rule of thumb stays the same: tail of the first, head of the last.\n\nWhen you draw a vector sum, mark the starting tail and the ending head before connecting them. Reversing the diagonal flips the result from sum to difference.",
