    explanation: "## Collinear Subtraction\n\nTwo vectors on the same line make subtraction easy: keep the direction of the larger vector and subtract the sizes.\n\n\\[ \\mathbf{A} - \\mathbf{B} = \\mathbf{A} + (-\\mathbf{B}) \\]\n\nBoth vectors point north. Written with south as negative:\n\\[ \\mathbf{A} = +5\\text{ units (north)} \\]\n\\[ \\mathbf{B} = +3\\text{ units (north)} \\]\n\\[ \\mathbf{A} - \\mathbf{B} = (+5) + (-3) = +2\\text{ units} \\]\n\nThe sign of the result is positive, so the direction is north, the same as \\(\\mathbf{A}\\). The magnitude is \\(2\\text{ units}\\).\n\nThe final direction is always the direction of the larger original vector. Here \\(\\mathbf{A}\\) wins, so the answer points north. If the two vectors had equal magnitudes, the result would be the null vector.\n\nWhen two vectors lie on the same line, subtract sizes and keep the winner's direction. When they do not lie on the same line, you must use components.",
