    explanation: "## Component by Component Subtraction\n\nVector subtraction distributes over components. Each component of \\(\\mathbf{B} - \\mathbf{C}\\) is the difference of that component from \\(\\mathbf{B}\\) and \\(\\mathbf{C}\\).\n\n\\[ \\mathbf{B} - \\mathbf{C} = (B_x - C_x)\\hat{i} + (B_y - C_y)\\hat{j} + (B_z - C_z)\\hat{k} \\]\n\nWrite the two vectors with matching structure:\n\\[ \\mathbf{B} = 5\\hat{i} - 3\\hat{j} + 1\\hat{k} \\]\n\\[ \\mathbf{C} = 2\\hat{i} + 1\\hat{j} - 2\\hat{k} \\]\nSubtracting each component:\n\\[ x: 5 - 2 = 3 \\]\n\\[ y: -3 - 1 = -4 \\]\n\\[ z: 1 - (-2) = 3 \\]\n\n\\[ \\mathbf{B} - \\mathbf{C} = 3\\hat{i} - 4\\hat{j} + 3\\hat{k} \\]\n\nThe z-component is where the arithmetic is easiest to trip on. Subtracting a negative is the same as adding, so \\(1 - (-2) = 1 + 2 = 3\\). A student who reads the sign of the second term incorrectly gets \\(-1\\) or \\(1\\) instead of 3.\n\nWhen subtracting vectors in component form, rewrite each term so every sign is visible, then subtract component by component.",
    status: "approved"
