    explanation: "## Reverse and Resize\n\nMultiplying a vector by a scalar does two things at once, and a negative scalar does both a magnitude change and a direction reversal.\n\n\\[ \\left|\\mathbf{B}\\right| = |k| \\cdot \\left|\\mathbf{A}\\right| \\]\n\\[ \\text{direction}(\\mathbf{B}) = \\text{opposite of } \\mathbf{A} \\]\n\nThe scalar's absolute value sets the new size. If \\(k = -3\\), the new vector is three times as long as \\(\\mathbf{A}\\):\n\\[ \\left|\\mathbf{B}\\right| = 3\\left|\\mathbf{A}\\right| \\]\nThe sign of \\(k\\) controls direction. Positive \\(k\\) preserves direction; negative \\(k\\) reverses it. With \\(k = -3\\), the vector points opposite to \\(\\mathbf{A}\\).\n\nFor example, if \\(\\mathbf{A}\\) has magnitude 2 pointing east, then \\(\\mathbf{B} = -3\\mathbf{A}\\) has magnitude 6 pointing west. Same line, opposite direction, larger size.\n\nWhen a scalar multiple appears, check the sign first and the absolute value second. Direction flips before size matters, and reversing the two checks produces the wrong answer.",
