    correct: 0,
    explanation: "## From Cross Product to Unit Vector\n\nA direction perpendicular to both given vectors comes from the cross product. Converting that cross product into a unit vector strips its magnitude while preserving the direction.\n\n\\[ \\hat{n} = \\frac{\\mathbf{A} \\times \\mathbf{B}}{\\left|\\mathbf{A} \\times \\mathbf{B}\\right|} \\]\n\n**Step 1. Cross product.** Using the determinant form:\n\\[ \\mathbf{A} \\times \\mathbf{B} = \\begin{vmatrix} \\hat{i} & \\hat{j} & \\hat{k} \\\\ 2 & 3 & 4 \\\\ 1 & -2 & 3 \\end{vmatrix} \\]\nExpanding along the first row:\n\\[ \\hat{i}\\,[(3)(3) - (4)(-2)] - \\hat{j}\\,[(2)(3) - (4)(1)] + \\hat{k}\\,[(2)(-2) - (3)(1)] \\]\n\\[ = \\hat{i}\\,[9 + 8] - \\hat{j}\\,[6 - 4] + \\hat{k}\\,[-4 - 3] \\]\n\\[ = 17\\hat{i} - 2\\hat{j} - 7\\hat{k} \\]\n\n**Step 2. Magnitude of the cross product.**\n\\[ \\left|\\mathbf{A} \\times \\mathbf{B}\\right| = \\sqrt{17^{2} + 2^{2} + 7^{2}} = \\sqrt{289 + 4 + 49} = \\sqrt{342} \\]\n\n\\[ \\hat{n} = \\frac{17\\hat{i} - 2\\hat{j} - 7\\hat{k}}{\\sqrt{342}} \\]\n\nEvery sign in the cross product is a place where a single slip flips the answer. When a problem asks for a unit vector perpendicular to two vectors, compute the cross product first, then divide by its magnitude. Check each component's sign against the determinant expansion.",
