    explanation: "## Two Velocities at Right Angles\n\nThe ship moves the passenger east. The passenger's walking moves them north. These two motions are perpendicular, so the combined velocity is the hypotenuse of a right triangle.\n\n\\[ \\left|\\mathbf{v}\\right| = \\sqrt{v_{\\text{east}}^{2} + v_{\\text{north}}^{2}} \\]\n\nWrite the two velocities as perpendicular components:\n\\[ v_{\\text{east}} = 12\\text{ m/s} \\]\n\\[ v_{\\text{north}} = 5\\text{ m/s} \\]\n\\[ \\left|\\mathbf{v}\\right| = \\sqrt{12^{2} + 5^{2}} \\]\n\n\\[ \\left|\\mathbf{v}\\right| = \\sqrt{144 + 25} = \\sqrt{169} = 13\\text{ m/s} \\]\n\nThe result sits between the two input magnitudes in a specific way. It is larger than either \\(12\\) or \\(5\\), but smaller than their sum \\(17\\). Only when the two velocities are perfectly aligned does the sum of magnitudes give the resultant magnitude. Perpendicularity makes the answer the hypotenuse.\n\nWhen two velocities are perpendicular, use Pythagoras, not ordinary addition.",
