    correct: 1,
    explanation: "## One Line, One Coordinate\n\nA car travelling on a straight road is like a bead on a wire. Its position at any moment is fixed by a single number: the distance along the road from a chosen origin.\n\n**One-dimensional motion** occurs when the object moves along a single straight line. Only one coordinate changes during the motion. The car cannot move sideways or up and down; it can only move forward or backward along the road.\n\nThe position vector is \\(\\mathbf{r} = x\\hat{i}\\). Only the x-coordinate varies with time, while y and z remain constant.\n\nTest each scenario by asking how many coordinates must be tracked. A boat on a lake needs two (latitude, longitude). An aeroplane needs three (plus altitude). A car on a straight road needs only one.\n\nThe classification depends purely on how many coordinates are required to locate the object as it moves. For the car on the straight road, only one coordinate is needed, so the motion is one-dimensional.\n\nWhen a problem describes motion, count how many coordinates change. One means the motion is one-dimensional, two means planar, three means spatial. The physics tools for each case differ accordingly."
