    correct: 1,
    explanation: "## How Far the Feet Walked\n\nA runner jogs around a 400 m circular track and returns to the start. The distance traveled is 400 m, even though the displacement is zero.\n\nThe **distance** covered by a particle is the actual length of the path traversed during a given time interval. It counts every step, in whatever direction, without regard for where the journey ends up.\n\nDistance is a scalar quantity, so there is no vector direction attached. The symbol is \\(d\\), and its SI unit is the metre (m).\n\nIf you drive 5 km east and then 5 km west, the distance is \\(5 + 5 = 10\\text{ km}\\). The displacement is \\(5 - 5 = 0\\text{ km}\\). Distance always adds the magnitudes of the path segments.\n\nThe distinction from displacement matters when a particle changes direction. A car that drives 5 km east and then 5 km back west has traveled a distance of 10 km, but its displacement is zero. Both quantities are correct; they describe different things.\n\nWhen a question asks 'how far did the object travel?' it is asking for distance. When it asks 'how far is the object from the start?' it is asking for displacement."
