    explanation: "## Distance Over Time in Action\n\nA 100 m sprint has known distance and known time. The average speed is a direct division.\n\n\\[ \\bar{v} = \\frac{\\text{total distance}}{\\text{total time}} \\]\n\n\\[ \\bar{v} = \\frac{100\\text{ m}}{9.58\\text{ s}} \\]\n\n\\[ \\bar{v} \\approx 10.44\\text{ m/s} \\]\nRounded to one decimal place, the answer is \\(10.4\\text{ m/s}\\) by convention.\n\nThe numbers 100 and 9.58 are tempting to mix up. If you divide time by distance, you get \\(0.096\\text{ m/s}\\), which is far too slow. If you multiply, you get 958, which is faster than sound. The sanity check catches both: any answer larger than \\(12\\text{ m/s}\\) is impossible for a human sprint.\n\nWhen a problem gives distance and time, always arrange the division so the answer has units of m/s. If it does not, the fraction is upside down."
