    explanation: "## Naming the Equation by What It Contains\n\nThe three kinematic equations each link a specific pair of physical quantities. Their names describe which quantities they connect, and once you know the names, choosing the right equation becomes fast.\n\nThe equation \\(v = v_{0} + at\\) relates velocity to time through acceleration. It contains no displacement, so it is the **velocity-time relation**.\n\n\\[ a = \\frac{v - v_{0}}{t} \\implies v = v_{0} + at \\]\n\nThe variables present are \\(v\\), \\(v_0\\), \\(a\\), and \\(t\\). Displacement (\\(s\\)) is absent. Therefore, the name must reflect velocity and time. \n\nWhen a problem gives initial velocity, acceleration, and time and asks for final velocity, this is the equation to use. The other two kinematic equations involve displacement, so they would be needed only if displacement were also a given.\n\nWhen choosing a kinematic equation, identify which quantities appear in the problem and which do not. The equation whose variable set matches the problem's knowns and unknown is the right one."
