    explanation: "## Two Phases, One Chain\n\nThe sprinter's motion splits into two intervals. The velocity at the end of the first interval becomes the starting velocity for the second. That chaining is the core of the problem.\n\n**The formula.**\nPhase 1 (Accelerating): \\(v_{1}^{2} = v_{0}^{2} + 2a_{1}s_{1}\\)\nPhase 2 (Decelerating): \\(v_{2}^{2} = v_{1}^{2} + 2a_{2}s_{2}\\)\n\n**Substituting.**\n**Phase 1:** \\(v_{1}^{2} = 0 + 2(1.5)(20) = 60\\)\n**Phase 2:** \\(v_{2}^{2} = 60 + 2(-0.1)(80) = 60 - 16 = 44\\)\n\n**Evaluating.**\n\\(v_{1} = \\sqrt{60} \\approx 7.746\\text{ m/s}\\)\n\\(v_{2} = \\sqrt{44} \\approx 6.633\\text{ m/s}\\)\nRounded to two decimal places, the final velocity is \\(6.64\\text{ m/s}\\).\n\nThe answer sits between the peak velocity \\(7.75\\text{ m/s}\\) and zero. The sprinter sped up quickly, then slowed slightly. That pattern is common in sprint races, where the acceleration phase is brief and the runner coasts on a mixture of speed and rhythm.\n\nWhen a problem has two distinct phases, chain the equations. Use the final velocity of one phase as the initial velocity of the next. Skipping the intermediate velocity is the most common way to lose the plot of the calculation."
