    correct: 0,
    explanation: "## A Body That Wants to Stay Put\n\nSlide a book across a smooth floor. It glides, and eventually it stops. Watch that motion carefully and you might conclude that a body needs a force to keep moving. Newton saw something else. He saw that the friction of the floor was the force, and the book would have kept going without it.\n\nNewton's First Law states that every body continues in its state of rest or uniform motion in a straight line, unless compelled by an external force to act otherwise. No force means no change in the state of motion.\n\nThe condition is expressed mathematically as:\n\\[ \\sum F = 0 \\implies v = \\text{constant} \\]\n\nThe word **external** matters. Forces internal to a system, like tension between parts of the same body, cannot change the motion of the whole. Only a force from outside the system can start it, stop it, or turn it.\n\nWhen a problem shows an object at rest or moving with constant velocity, check whether the net external force is zero. If it is, the First Law is satisfied and the object stays as it is. If the object is accelerating, an external force must be present, and the problem belongs to the Second Law.",
