    correct: 1,
    explanation: "## Hard to Start, Hard to Stop\n\nTry pushing a shopping trolley empty and then loaded. The loaded one resists you more, even on the same floor. The difference is not friction but mass. The heavier trolley has more inertia.\n\n**Inertia** is the property of a body by which it tends to resist change in its state of rest or uniform motion in a straight line. It is not a force. It is a measure of how strongly the body holds onto whatever motion it already has.\n\nMass is the quantitative measure of inertia. It appears in the Second Law as the resistance to acceleration:\n\\[ m = \\frac{F}{a} \\]\n\nA more massive body has more inertia and requires a larger force to change its velocity in a given time. The two statements are two sides of the same physics.\n\nWhen a problem asks why an object stays at rest or keeps moving, check the net force. If the net force is zero, the object stays in motion because of inertia. If a body changes motion easily, its mass is small; if it resists, its mass is large.",
