    correct: 2,
    explanation: "## The Puck That Never Stops\n\nOn a perfectly smooth ice surface with no friction, no air resistance, and no other forces, a sliding puck behaves like the idealized object Newton imagined. Nothing changes its motion.\n\nThe First Law predicts the puck's velocity vector stays constant:\n\\[ v = \\text{constant} \\]\n\nAny slowing down or curving would require a horizontal force. Frictionless removes friction. Straight motion means no sideways force. With no horizontal force of any kind, the puck cannot accelerate.\n\nReal hockey pucks do slow down, but only because real ice has friction. In the ideal case, no force means no change, and the puck coasts forever. That gap between the ideal and the real is what makes the First Law a useful physics tool. It describes what would happen if the world were simpler, and from that simplification the Second Law can be built.",
