    explanation: "## Building a Unit From the Law\n\nEvery SI derived unit has a precise definition that traces back to the base units. The Newton is defined through the Second Law because force is what the Second Law relates to acceleration.\n\nOne Newton is the force that gives a mass of one kilogram an acceleration of one metre per second squared:\n\\[ 1\\text{ N} = 1\\text{ kg} \\cdot \\text{m/s}^{2} \\]\n\nThe definition fixes the relationship between the units of force, mass, and acceleration. If any two are defined, the third follows.\n\nWeight and Newton are not the same. The weight of a \\(1\\text{ kg}\\) mass near Earth's surface is \\(mg = 1 \\times 9.8 = 9.8\\text{ N}\\), not 1 N. The Newton is a general unit of force, and weight is only one specific force measured in it.\n\nWhen a problem gives a force in some other unit, convert to Newtons before applying \\(F = ma\\).",
