    q: "A bullet of mass \\(10\\text{ g}\\) travelling at \\(100\\text{ m/s}\\) strikes a \\(50\\text{ cm}\\) thick wooden plank and emerges at \\(30\\text{ m/s}\\). What resistance does the plank offer?",
