    correct: 2,
    explanation: "## Deceleration Inside the Plank\n\nThe bullet loses speed inside the plank. The distance over which the speed drops is the plank's thickness, so the deceleration and the force both follow.\n\n\\[ v^{2} = v_{0}^{2} + 2as \\]\n\\[ F = ma \\]\n\n**Step 1. Convert to SI units.**\n\\[ m = 10\\text{ g} = 0.01\\text{ kg}, \\quad s = 0.50\\text{ m} \\]\n**Step 2. Deceleration.**\n\\[ (30)^{2} = (100)^{2} + 2a(0.50) \\]\n\\[ 900 = 10000 + a \\]\n\\[ a = -9100\\text{ m/s}^{2} \\]\n**Step 3. Force.**\n\\[ F = 0.01 \\times 9100 = 91\\text{ N} \\]\n\nThe bullet decelerates at over nine hundred times the acceleration of gravity over a distance of half a metre. That enormous deceleration produces a resistance of \\(91\\text{ N}\\), a modest force by human standards but significant for a tiny projectile.\n\nThe material thickness matters. If the plank were half as thick, the deceleration would be twice as large.\n\nWhen a bullet passes through a medium, use the two-velocity kinematic equation to find deceleration, then apply \\(F = ma\\).",
