    correct: 2,
    explanation: "## Two Forces on Two Bodies Cannot Cancel\n\nPush a book across a table. Your hand pushes the book forward, and the book pushes your hand backward. Both forces exist, at the same time, with equal size. Yet the book accelerates forward and your hand does not accelerate backward. Why?\n\nBecause the two forces act on **different bodies**. The forward force acts on the book, and the backward force acts on your hand. Cancellation only happens when two forces act on the same body and sum to zero. The action and reaction pair never do that.\n\n\\[ \\sum F_{\\text{on body 1}} = \\text{Action} \\neq 0 \\]\n\\[ \\sum F_{\\text{on body 2}} = \\text{Reaction} \\neq 0 \\]\n\nA pair that does cancel is a different kind of pair. In a book at rest on a table, the book's weight pulls it down and the table's normal force pushes it up. Both forces act on the book, and both sum to zero, keeping the book in equilibrium. This is not a Third Law pair; it is a normal equilibrium.\n\nThird Law pairs and equilibrium pairs can be confused because both involve equal and opposite forces. The distinguishing feature is where they act. Third Law forces act on two different bodies and cannot cancel. Equilibrium forces act on one body and do cancel.\n\nWhen you see two forces with equal magnitude and opposite direction, check which body they act on.",
