    correct: 1,
    explanation: "## The Pair That Is Not a Pair\n\nA book sits on a table. Weight pulls it down. The normal force pushes it up. The two forces are equal and opposite. That looks like the Third Law. It is not.\n\nNewton's Third Law requires the two forces to act on **two different bodies**. The two forces here both act on the book. The weight acts on the book because of the Earth. The normal force acts on the book because of the table. Both forces act on the book, and both contribute to its equilibrium.\n\nFor equilibrium on the same body:\n\\[ \\sum F = N - mg = 0 \\]\nFor the Third Law pair of weight:\n\\[ F_{\\text{book on Earth}} = -F_{\\text{Earth on book}} \\]\n\nThe true Third Law pair to the book's weight is the gravitational pull the book exerts on the Earth. That force acts on the Earth, not on the book. The true Third Law pair to the normal force is the force the book exerts on the table, pointing down. Both of those pairs involve two different bodies.\n\nThe confusion is common because both types of pair look alike on paper. The distinction lies in what the forces act on. Same body means equilibrium. Two bodies means Third Law.\n\nWhen you identify forces on a diagram, name the pair carefully. If both forces act on the same object, they belong in that object's free body diagram. If one force acts on each of two bodies, they are a Third Law pair and never appear in the same diagram.",
