    correct: 0,
    explanation: "## What Stays and What Changes\n\nA cosmonaut travels from Earth to Venus. Her body is made of the same matter, but the pull of gravity is different on Venus. What stays and what changes is the whole point of this problem.\n\n\\[ m = \\frac{W}{g} \\]\n\\[ W = mg \\]\n\n**Mass stays constant.** Mass is the amount of matter, and it does not depend on the planet. Divide the Earth weight by the Earth value of g to find it:\n\\[ m = \\frac{588\\text{ N}}{9.8\\text{ N/kg}} = 60\\text{ kg} \\]\n**Weight changes with g.** On Venus:\n\\[ W_{\\text{Venus}} = 60 \\times 8.6 = 516\\text{ N} \\]\n\nHer weight on Venus is less than on Earth because Venus's gravity is slightly weaker. The mass is identical.\n\nVenus's gravity is about 88 percent of Earth's, so the weight drops by the same proportion. On the Moon, the drop would be far more dramatic, with weight only about 16 percent of Earth's.\n\nWhen a problem involves a change of planet, always separate the two. Mass is found by dividing weight by the local g. Weight is found by multiplying mass by the new local g.",
