    correct: 2,
    explanation: "## The Moment of Sliding\n\nA mass sits on a rough table. Push gently and nothing happens. Push harder and it still sits. Then, at some precise push, it starts to slide. That threshold push is the maximum static friction.\n\n**The formula.**\n\\[ N = mg \\]\n\\[ f_{s,\\text{max}} = \\mu_{s}N \\]\n\n**Substituting.**\n**Step 1. Normal force.**\n\\[ N = 45 \\times 9.8 = 441\\text{ N} \\]\n**Step 2. Set to applied force.**\n\\[ 98 = \\mu_{s}(441) \\]\n\n**Evaluating.**\n\\[ \\mu_{s} = \\frac{98}{441} \\approx 0.22 \\]\n\nThe coefficient is dimensionless, as it should be. All friction coefficients are pure numbers in the range of roughly \\(0.05\\) to \\(1.5\\), depending on the surfaces. Wood on wood is typically around \\(0.4\\), while rubber on concrete is higher.\n\nWhen a problem gives the threshold force needed to start motion, that force equals the maximum static friction.",
