    correct: 2,
    explanation: "## Moving Steadily, Feeling Normal\n\nA lift glides upward at a steady speed. Nothing inside feels different. The floor supports the body exactly as it would in a stationary room.\n\nThe key fact is that **constant velocity means zero acceleration**. Regardless of the direction of motion, if the velocity is not changing, the acceleration is zero.\n\n\\[ N - mg = ma = 0 \\]\n\n\\[ N = mg \\]\n\nThe direction of motion does not enter this result. A lift moving up at constant speed feels the same as a lift moving down at constant speed. Only the sign of the displacement changes; the forces do not.\n\nThe result contradicts a common intuition that upward motion must feel heavier. That intuition confuses motion with acceleration. Being in motion and being accelerated are different conditions. A train moving smoothly at \\(300\\text{ km/h}\\) feels indistinguishable from one at rest, so long as neither is accelerating.\n\nWhen a problem gives constant velocity, do not apply any extra apparent weight formula.",
