    explanation: "## Heavier When the Floor Pushes Harder\n\nPress the button for the top floor and feel a brief weight increase as the lift accelerates. That sensation is not imagination. The floor is pushing harder than usual because it now has to do two jobs.\n\nWhen the lift accelerates upward, the floor must support the weight and provide the upward acceleration. That means the normal force exceeds the weight.\n\nTaking upward as positive:\n\\[ N - mg = ma \\]\n\nSolving for \\(N\\):\n\\[ N = mg + ma = m(g + a) \\]\n\nThe apparent weight is larger than the actual weight. The extra force matches the extra acceleration the floor must provide.\n\nThe **apparent weight** is the normal force, not a new kind of weight. The body has not gained mass, and gravity has not gotten stronger. The floor is simply pushing harder. A bathroom scale in the lift would read the apparent weight.\n\nWhen a lift accelerates upward, use \\(N = m(g+a)\\).",
