    explanation: "## Lighter When the Floor Gives Way\n\nFeel the sensation at the moment a lift starts descending. The floor seems to drop away, and for a moment the body feels lighter. The physics is that the floor is pushing with less force because part of the downward force is already accelerating the body.\n\nWhen the lift accelerates downward, the weight does more than support the body. It also provides some of the downward acceleration. The floor's share of the support is therefore reduced.\n\nTaking downward as positive:\n\\[ mg - N = ma \\]\n\nSolving for \\(N\\):\n\\[ N = mg - ma = m(g - a) \\]\n\nThe apparent weight is smaller than the actual weight. The floor pushes less than the body's weight.\n\nAs \\(a\\) grows toward \\(g\\), \\(N\\) shrinks toward zero. At \\(a = g\\), the floor pushes with no force at all, and the body is apparently weightless.\n\nWhen a lift accelerates downward with \\(a < g\\), use \\(N = m(g-a)\\).",
