    explanation: "## The Feeling of Free Fall\n\nAstronauts in orbit float, weightless. So do passengers in a lift whose cable has snapped, for the few seconds before impact. The physics is the same: the floor is falling just as fast as the body, so nothing presses the body to the floor.\n\nA freely falling lift accelerates downward at exactly \\(g\\). \n\n\\[ N = m(g - a) \\]\n\nSubstituting \\(a = g\\):\n\\[ N = m(g - g) = 0 \\]\n\nThe normal force is zero. The body is still subject to gravity, and it still accelerates at \\(g\\), but it feels no support. The floor cannot push because it is falling too.\n\nThis is the definition of **apparent weightlessness**. The body has weight (gravity is still acting), but the normal force is zero, so the body cannot tell it is being pulled down. Any loose object inside the lift floats.\n\nThis is the same experience astronauts have in orbit. They are not outside Earth's gravity; the space station is in continuous free fall around the Earth.",
