    correct: 1,
    explanation: "## A Push at an Angle\n\nA force applied to a door at \\(60^\\circ\\) does not have the full turning effect that a perpendicular force would. Only the component perpendicular to the door contributes to the moment about the hinge.\n\n\\[ \\tau = F_{\\perp} \\times r \\]\n\\[ F_{\\perp} = F\\sin\\theta \\]\n\n**Step 1. Perpendicular component of the force.**\n\\[ F_{\\perp} = 15 \\times \\sin 60^\\circ \\]\n\\[ F_{\\perp} = 15 \\times 0.866 = 12.99\\text{ N} \\]\n**Step 2. Perpendicular distance.** The door is \\(0.80\\text{ m}\\) wide.\n\\[ \\tau = 12.99 \\times 0.80 \\]\n\n\\[ \\tau \\approx 10.4\\text{ N}\\cdot\\text{m} \\]\n\nA perpendicular force of \\(15\\text{ N}\\) would give a moment of \\(12\\text{ N}\\cdot\\text{m}\\). The angle reduces the effective turning effect to about \\(10.4\\text{ N}\\cdot\\text{m}\\), roughly 87 percent of the perpendicular case.\n\nWhen a force acts at an angle to the lever arm, split it into perpendicular and parallel components. The perpendicular component produces the torque. The parallel component does not contribute because its line of action passes through the pivot.",
