    explanation: "## Weight Off-Centre\n\nA painter stands on a plank supported at both ends. Because the painter is closer to one end, that end carries more weight. The principle of moments determines how the 900 N splits between the two supports.\n\n\\[ \\sum \\tau = 0 \\]\n\\[ \\sum F_{y} = 0 \\]\n\n**Step 1. Choose a pivot to simplify.** Take moments about support A. That eliminates \\(F_{A}\\) from the equation, leaving one unknown.\n\\[ F_{B} \\times 5 = 900 \\times 1 \\]\n**Step 2. Solve for \\(F_{B}\\).**\n\\[ F_{B} = \\frac{900}{5} = 180\\text{ N} \\]\n**Step 3. Vertical equilibrium.**\n\\[ F_{A} + F_{B} = 900 \\]\n\n\\[ F_{A} = 900 - 180 = 720\\text{ N} \\]\n\nSupport A carries 720 N and support B carries 180 N. Since the painter is 1 m from A and 4 m from B, A has to carry four times as much. The distances are in the ratio 1:4, and the forces are in the opposite ratio 4:1.\n\nThe massless-plank assumption keeps the problem simple. If the plank had mass, its weight would also need to be included, with its own weight acting at the plank's centre.\n\nWhen a load sits on a beam supported at both ends, take moments about one support to find the other's reaction, then use vertical equilibrium to find the first.",
