    explanation: "## Load Near One End\n\nA 5 kN load sits 1 m from support A on a 2.5 m rod. The support closer to the load takes more of the weight, and the reaction at A will be larger than the reaction at B.\n\n\\[ \\sum \\tau = 0 \\]\n\\[ \\sum F_{y} = 0 \\]\n\n**Step 1. Choose A as pivot.** This eliminates \\(R_{A}\\) from the moment equation.\n\\[ R_{B} \\times 2.5 = 5 \\times 1 \\]\n**Step 2. Solve for \\(R_{B}\\).**\n\\[ R_{B} = \\frac{5}{2.5} = 2\\text{ kN} \\]\n**Step 3. Vertical equilibrium.**\n\\[ R_{A} + R_{B} = 5 \\]\n\n\\[ R_{A} = 5 - 2 = 3\\text{ kN} \\]\n\nSupport A carries 3 kN and support B carries 2 kN. The load is 1 m from A and 1.5 m from B, so the distances are in the ratio 2:3 and the forces are in the opposite ratio 3:2. The closer support carries more.\n\nNote the units. The load is in kN, the reactions come out in kN. Since the ratio of moments has units of force times distance on both sides, they cancel, and the answer inherits the force unit of the load.\n\nWhen a load is closer to one support than the other, that support carries more. The reactions are always in the inverse ratio of the distances.",
