    explanation: "## Throwing From a Tower\n\nThe stone leaves the top of the tower horizontally, so its initial vertical velocity is zero. Its horizontal velocity is whatever it was launched with. The time of flight is fixed by the height of the tower, not by the horizontal motion.\n\nFirst find the time of flight from the vertical fall, then find the horizontal speed that covers the horizontal distance in that time.\n\n**The formula.**\nVertical fall:\n\\[ h = \\tfrac{1}{2}gt^{2} \\]\nHorizontal motion:\n\\[ x = v_{x}t \\]\n\n**Substituting.**\nTime of flight:\n\\[ 24 = \\tfrac{1}{2}(9.8)t^{2} = 4.9t^{2} \\]\n\\[ t^{2} = \\frac{24}{4.9} \\approx 4.898 \\]\n\\[ t \\approx 2.213\\text{ s} \\]\nHorizontal speed:\n\\[ v_{x} = \\frac{18}{2.213} \\approx 8.13\\text{ m/s} \\]\n\n**Evaluating.**\nThe stone was thrown at about 8.13 m/s. That is a reasonable speed for a thrown stone, well within human limits.\n\nThe two motions are independent. The vertical fall depends only on the height of the tower. The horizontal distance depends only on the horizontal speed and the time of flight. Neither is affected by the other.\n\nWhen a projectile is launched horizontally, find the time of flight from the fall distance. Then use that time to find the horizontal speed."
