    mainTopic: "Unit 4: Force and Motion",
    topic: "4.1.2 Second Law",
    q: "An object of mass \\(10\\text{ g}\\) is moving along the x-axis. Its position as a function of time is given by \\(x = (4t^{3} + 2t)\\text{ m}\\). What is the magnitude of the force acting on the object at \\(t = 2\\text{ s}\\)?",
    options: [
      "\\(0.52\\text{ N}\\)",
      "\\(0.13\\text{ N}\\)",
      "\\(0.35\\text{ N}\\)",
      "\\(0.48\\text{ N}\\)"
    ],
    optionRationales: [
      "0.52 N doubles the correct force.",
      "0.13 N is half the correct force.",
      "0.35 N uses the wrong acceleration components.",
      null
    ],
    correct: 3, // Position D
    explanation: "## Force From a Position Function\n\nThe position of the object is given as a function of time. From that function, velocity and acceleration follow by differentiation. Once acceleration is known, the Second Law gives the force.\n\n**The formula.**\n\\[ v = \\frac{dx}{dt} \\]\n\\[ a = \\frac{dv}{dt} \\]\n\\[ F = ma \\]\n\n**Substituting.**\n\\[ x = 4t^{3} + 2t \\]\n\\[ v = 12t^{2} + 2 \\]\n\\[ a = 24t \\]\nAt \\(t = 2\\text{ s}\\):\n\\[ a = 24(2) = 48\\text{ m/s}^{2} \\]\n\\[ F = (0.01)(48) = 0.48\\text{ N} \\]\n\n**Evaluating.**\n\\[ F = 0.48\\text{ N} \\]\n\nThe object's mass is 10 g, which is 0.01 kg. The acceleration at \\(t=2\\) is 48 m/s², and the force follows directly. The answer is a fraction of a Newton, which makes sense for such a small mass.\n\nWhen a position function is given, differentiate twice to find acceleration, then multiply by mass. The process is the same in one, two, or three dimensions."
