    options: [
      "\\(308.6\\text{ m}\\)",
      "\\(300.0\\text{ m}\\)",
      "\\(291.4\\text{ m}\\)",
      "\\(313.0\\text{ m}\\)"
    ],
    optionRationales: [
      null,
      "300.0 m assumes the bag is dropped from rest at the moment of release, ignoring the upward velocity of the balloon.",
      "291.4 m incorrectly subtracts the height gained instead of adding it.",
      "313.0 m treats the release velocity as entirely vertical upward without accounting for gravity."
    ],
    correct: 0, // Position A
    explanation: "## Dropped From a Rising Balloon\n\nA balloon is rising at \\(13\\text{ m/s}\\) when a bag is dropped from it. The bag leaves the balloon with the balloon's upward velocity. The bag therefore continues to rise for a while before gravity brings it back down.\n\nThe bag's initial velocity is upward at \\(13\\text{ m/s}\\), and its initial height is \\(300\\text{ m}\\). The maximum height is the release height plus whatever extra height the bag gains during the upward phase of its flight.\n\n**The formula.**\n\\[ v^{2} = v_{0}^{2} - 2g\\Delta y \\]\nAt maximum height, \\(v = 0\\):\n\\[ \\Delta y = \\frac{v_{0}^{2}}{2g} \\]\n\\[ H = H_{\\text{release}} + \\Delta y \\]\n\n**Substituting.**\n\\[ \\Delta y = \\frac{(13)^{2}}{2(9.8)} \\]\n\\[ \\Delta y = \\frac{169}{19.6} \\]\n\\[ \\Delta y \\approx 8.6\\text{ m} \\]\n\\[ H = 300 + 8.6 \\]\n\n**Evaluating.**\n\\[ H = 308.6\\text{ m} \\]\n\nThe bag rises an extra 8.6 m above the release point before starting to fall. That extra height is small compared to the 300 m release point, but it is the difference between a correct and an incorrect answer.\n\nThe trap is to assume the bag was dropped from rest. Dropped from a moving balloon, the bag has the balloon's velocity, and that upward velocity takes time to lose."
