  {
    id: "PH110-T1-EXAM-2018-002",
    mainTopic: "Unit 4: Force and Motion",
    topic: "4.2.4 Friction",
    q: "A mini bus is moving at \\(72\\text{ km/h}\\) on a horizontal straight rough road. Just before reaching the CBU station, the engine suddenly switches off and the bus skids to a stop through a distance of \\(50\\text{ m}\\). Calculate the coefficient of kinetic friction between the road and the bus's tyres.",
    options: [
      "\\(0.20\\)",
      "\\(0.41\\)",
      "\\(0.61\\)",
      "\\(0.82\\)"
    ],
    optionRationales: [
      "0.20 is half the correct value.",
      null,
      "0.61 uses a higher speed or a shorter distance.",
      "0.82 is double the correct value."
    ],
    correct: 1, // Position B
    explanation: "## Skidding to a Stop\n\nThe engine is off. The only horizontal force acting on the bus is kinetic friction, which opposes the motion. The friction force determines the deceleration, and the deceleration determines the stopping distance.\n\nThe stopping distance is given, and the initial speed is given. From the two, the deceleration follows by kinematics. The friction coefficient then comes from the Second Law.\n\n**The formula.**\n\\[ v^{2} = v_{0}^{2} + 2as \\]\n\\[ f_{k} = \\mu_{k}mg \\]\n\\[ \\mu_{k}mg = ma \\implies a = \\mu_{k}g \\]\n\n**Substituting.**\nConvert speed to SI:\n\\[ v_{0} = 72\\text{ km/h} = 20\\text{ m/s} \\]\nFinal velocity is zero:\n\\[ 0 = (20)^{2} + 2a(50) \\]\n\\[ 0 = 400 + 100a \\]\n\\[ a = -4\\text{ m/s}^{2} \\]\nThe friction coefficient:\n\\[ \\mu_{k} = \\frac{|a|}{g} = \\frac{4}{9.8} \\]\n\n**Evaluating.**\n\\[ \\mu_{k} \\approx 0.41 \\]\n\nA coefficient of 0.41 is realistic for rubber tyres on a dry road. Wet roads have lower coefficients, which is why stopping distances grow on wet days.\n\nThe mass of the bus cancels out of the calculation. The friction force scales with mass, but so does the inertia, and the two effects exactly cancel.\n\nWhen a vehicle skids to a stop, use the kinematic equation with final velocity zero to find deceleration, then use \\(\\mu_{k} = |a|/g\\) to get the coefficient."
  }
